import{_ as a,o as t,c as i,a3 as r,j as e,a as l}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/unterricht-kataloge/kataloge-schuelergruppe-schuelerhinzufuegen.png",p="/bilder/unterricht-kataloge/kataloge-schuelergruppe-auswahl.png",s="/bilder/unterricht-kataloge/kataloge-schuelergruppen-01.png",m=JSON.parse('{"title":"Individuelle Schülergruppen im Katalog verwalten","description":"","frontmatter":{"title":"Individuelle Schülergruppen im Katalog verwalten","source_pageid":314,"source_revision":7155},"headers":[],"relativePath":"schild3/unterricht-kataloge/schuelergruppe-bearbeiten-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/schuelergruppe-bearbeiten-schulbezogene-kataloge.md"}'),g={name:"schild3/unterricht-kataloge/schuelergruppe-bearbeiten-schulbezogene-kataloge.md"};function c(o,n,h,d,S,b){return t(),i("div",null,[...n[0]||(n[0]=[r('<h1 id="individuelle-schulergruppen-im-katalog-verwalten" tabindex="-1">Individuelle Schülergruppen im Katalog verwalten <a class="header-anchor" href="#individuelle-schulergruppen-im-katalog-verwalten" aria-label="Permalink to &quot;Individuelle Schülergruppen im Katalog verwalten&quot;">​</a></h1><p>Legen Sie benannte Schülergruppen an, bearbeiten Sie diese und ordnen Sie Schülerinnen und Schüler zu. Die Gruppen können später gezielt als Auswahl aufgerufen werden.</p><p>Durch <strong>Schülergruppen</strong> können beliebige Schülerinnen und Schülern zusammengefasst werden mit dem Ziel, sich diese Gruppe an Schülerinnen und Schülern in der Zukunft schnell wieder von SchILD anzeigen zu lassen.</p><p>Die Gruppenzusammensetzung kann dabei <strong>individuell</strong> festgelegt werden, ebenso die Bezeichnungen dieser Gruppen.</p><p>Nach Festlegung der verwendeten Schülergruppen in diesem Programmfenster können einzelne oder auch mehrere Schülerinnen und Schüler diesen Gruppen <strong>zugewiesen</strong> werden.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schuelergruppe-schuelerhinzufuegen.png"><img src="'+u+'" alt="Fügen Sie Schüler einer Schülergruppe hinzu." loading="lazy"></a></p><p><em>Fügen Sie Schüler einer Schülergruppe hinzu.</em></p><p>Markieren Sie Schüler im Schülercontainer und verwenden Sie dann die <code>Rechte Maustaste</code>, um das Kontextmenü aufzurufen.</p><p>Klicken Sie dann auf <code>Markierte Datensätze zu individueller Schülergruppe hinzufügen</code>.</p><p>Im Fenster, das sich nun öffnet, wird die gewünschte Schülergruppe ausgewählt. Klicken Sie dann auf <code>Übernehmen</code>.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schuelergruppe-auswahl.png"><img src="'+p+'" alt="Wählen Sie eine existierende Schülergruppe aus." loading="lazy"></a></p><p><em>Wählen Sie eine existierende Schülergruppe aus.</em></p><p>Um eine Schülergruppe auszuwählen, gehen Sie über den Reiter <strong>Auswahl</strong> und klicken dort auf <strong>Schülergruppe</strong>.</p><p>Haben Sie die gewünschte Schülergruppe angeklickt, sind diese Schüler nun im Schülercontainer gefiltert.</p><h2 id="anlegen-neuer-schulergruppen" tabindex="-1">Anlegen neuer Schülergruppen <a class="header-anchor" href="#anlegen-neuer-schulergruppen" aria-label="Permalink to &quot;Anlegen neuer Schülergruppen&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-schuelergruppen-01.png"><img src="'+s+'" alt="Übersicht über das Fenster Kataloge ➜ Schülergruppen bearbeiten." loading="lazy"></a></p><p><em>Übersicht über das Fenster Kataloge ➜ Schülergruppen bearbeiten.</em></p><p>Durch Klick auf das &quot;+&quot; kann eine neue Schülergruppe <strong>angelegt</strong> werden. In der Spalte &quot;Bezeichnung&quot; wird die entsprechende Bezeichnung eingetragen.</p><p>Die Einträge werden alphabetisch sortiert.</p><p>In der Spalte &quot;Erzeugt von&quot; wird der aktuell in SchILD angemeldete Benutzername eingetragen.</p><h2 id="bearbeiten-von-schulergruppen" tabindex="-1">Bearbeiten von Schülergruppen <a class="header-anchor" href="#bearbeiten-von-schulergruppen" aria-label="Permalink to &quot;Bearbeiten von Schülergruppen&quot;">​</a></h2>',21),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),l("Hinweis")]),e("p",null,"Es können nur diejenigen Schülergruppen bearbeitet werden, die vom aktuell angemeldeten Benutzernamen selbst angelegt worden sind. Dies betrifft ebenfalls das Löschen einer Schülergruppe.")],-1),r('<p>Durch einen Doppelklick in das entsprechende Feld in der Spalte &quot;Bezeichnung&quot; kann die Bezeichnung bereits angelegter Schülergruppen <strong>geändert</strong> werden.</p><p>Ein Klick auf das &quot;-&quot; <strong>löscht</strong> die angelegte Schülergruppe nach Bestätigung einer Dialogabfrage.</p><p>Im Fenster &quot;Mitglieder der Gruppe&quot; können durch einen Klick auf &quot;Markierte Schüler aus der Gruppe entfernen&quot; diejeningen Schülerinnen und Schüler <strong>aus der Gruppe gelöscht</strong> werden, vor deren Namen ein Häkchen gesetzt wurde.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sch%C3%BClergruppe_bearbeiten_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7155.</p>',5)])])}const f=a(g,[["render",c]]);export{m as __pageData,f as default};
